import test from 'node:test'
import assert from 'node:assert/strict'
import {SCENARIOS,createSession,assess,sendMessage,chooseDomain,restoreDraft,classifyIntent,updateFields,preparePublish,confirm,publicationPreview,fieldDefs,undo,cancel} from '../src/engine.js'
const fixes={spec:'USB-C 输入 / HDMI 输出，本人核实',needBy:'2026-10-14T18:30',deliveryConsent:'待与出借方协商',accessories:'电池与存储卡，是否提供待核实',returnPlace:'示例校区6号宿舍门厅',depth:'从基础讲',priority:'弄懂符号变化',communication:'线上异步',language:'中英双语',context:'第二步 x = -2，第三步 -x = 2',handling:'一件约5千克，送到一层门厅，能力待协商',notice:'静默消息',pickupPlace:'示例校区北门快递站柜台',dropPlace:'示例校区6号宿舍一层门厅左侧置物架',resourceRequirements:'用户电脑Windows系统，连接时出现错误提示',helperCount:'2',servicePlace:'线上，通过平台任务消息联系',serviceStart:'2026-10-14T19:00',completionCriteria:'按约定将指定活动物料分类并由发布者核对'}
const ready=id=>{const x=SCENARIOS.find(s=>s.id===id),s=createSession(x.domain,id);updateFields(s,{[x.missing]:fixes[x.missing]});if(id==='O02')updateFields(s,{splitMode:'由一人协调（模拟）'});return s}
test('four categories each contain five design hypotheses',()=>{assert.equal(SCENARIOS.length,20);for(const domain of ['BORROW','STUDY','RUNNING','OTHER'])assert.equal(SCENARIOS.filter(x=>x.domain===domain).length,5)})
for(const x of SCENARIOS)test(`${x.id} can clarify and simulate publication with its real category`,()=>{const s=ready(x.id);assert.equal(assess(s).ready,true,JSON.stringify(assess(s)));preparePublish(s);assert.equal(confirm(s),false);updateFields(s,{expectedTime:'2026-10-19T21:00',reward:'5',location:'示例校区图书馆东门'});assert.equal(confirm(s),true,JSON.stringify(assess(s)));assert.equal(publicationPreview(s).category,x.domain)})
for(const [domain,text] of [['BORROW','想借相机拍校园活动'],['STUDY','导数定义怎么理解'],['RUNNING','帮我代取快递'],['OTHER','电脑连不上校园网，想找人帮忙看看']])test(`unified entry suggests ${domain} but waits for user choice`,()=>{const s=createSession('AUTO');sendMessage(s,text);assert.deepEqual(s.routing.candidates,[domain]);assert.equal(confirm(s),false);assert.equal(preparePublish(s),false);chooseDomain(s,domain);assert.equal(s.domain,domain);assert.equal(s.routing,null);assert.ok(s.messages.some(m=>m.text===text))})
test('unclear goals are not silently assigned to OTHER',()=>{const s=createSession('AUTO');sendMessage(s,'帮我处理一下那个事');assert.deepEqual(s.routing.candidates,[]);assert.equal(assess(s).ready,false);chooseDomain(s,'OTHER');assert.equal(s.fields.serviceGoal,'帮我处理一下那个事');assert.ok(assess(s).missing.includes('completionCriteria'))})
test('mixed goals require a choice and never combine category fields',()=>{const s=createSession('AUTO');sendMessage(s,'想借相机，还需要代取快递');assert.deepEqual(s.routing.candidates,['BORROW','RUNNING']);chooseDomain(s,'RUNNING');assert.equal(s.fields.returnAt,undefined);assert.equal(s.fields.taskKind,'代取快递');assert.equal(confirm(s),false)})
test('corrected business intent ignores the negated previous category',()=>assert.deepEqual(classifyIntent('不是借相机，是帮我代取快递'),['RUNNING']))
test('switching domains archives original draft and restoring revokes confirmation',()=>{const s=ready('B01'),original=s.fields.returnAt;confirm(s);sendMessage(s,'现在帮我代取快递');assert.equal(s.domain,'BORROW');assert.equal(confirm(s),false);assert.equal(s.confirmation,null);chooseDomain(s,'RUNNING');assert.equal(s.fields.returnAt,undefined);assert.equal(s.suspendedDrafts.length,1);restoreDraft(s,0);assert.equal(s.domain,'BORROW');assert.equal(s.fields.returnAt,original);assert.equal(s.confirmation,null);assert.equal(s.suspendedDrafts[0].domain,'RUNNING')})
test('explicit current-domain structured corrections do not route on incidental keywords',()=>{const s=ready('B01');sendMessage(s,'用途：拍校园活动');assert.equal(s.routing,null);assert.equal(s.fields.purpose,'拍校园活动')})
test('ambiguous drop point blocks courier confirmation',()=>{const s=ready('R05');updateFields(s,{dropPlace:'附近某个地方'});assert.equal(confirm(s),false);assert.match(assess(s).risks.join(' '),/放置点不明确/)})
test('courier handoff change clears old proof and location',()=>{const s=ready('R05');confirm(s);updateFields(s,{handoff:'当面交付'});assert.equal(s.confirmation,null);assert.equal(s.fields.dropPlace,undefined);assert.equal(confirm(s),false);updateFields(s,{completionProof:'当面确认'});assert.equal(confirm(s),true)})
test('courier time conflict cannot be confirmed',()=>{const s=ready('R05');updateFields(s,{latestDelivery:'2026-10-14T15:00'});assert.equal(confirm(s),false);assert.match(assess(s).risks.join(' '),/时间窗口/)})
test('quiet notification constraint survives text and conflicts with phone',()=>{const s=ready('R01');sendMessage(s,'请别打电话');updateFields(s,{notice:'电话'});assert.equal(confirm(s),false);assert.match(assess(s).risks.join(' '),/静默/);updateFields(s,{notice:'静默消息'});assert.equal(confirm(s),true)})
test('courier purchase budget is required and cannot mean paid',()=>{const s=ready('R05');updateFields(s,{taskKind:'代买物品'});assert.ok(assess(s).missing.includes('costLimit'));updateFields(s,{costLimit:'-1'});assert.equal(confirm(s),false);updateFields(s,{costLimit:'20'});assert.equal(confirm(s),true);assert.equal(s.fields.paymentStatus,undefined)})
test('drop location and purchase budget controls are conditional',()=>{const s=ready('R05');assert.ok(fieldDefs(s).some(f=>f.key==='dropPlace'));assert.equal(fieldDefs(s).some(f=>f.key==='costLimit'),false);updateFields(s,{taskKind:'代买物品'});assert.ok(fieldDefs(s).some(f=>f.key==='costLimit'))})
test('OTHER must have a meaningful completion scope and valid time interval',()=>{const s=ready('O05');updateFields(s,{completionCriteria:'帮忙'});assert.equal(confirm(s),false);updateFields(s,{completionCriteria:'指定清单完成',serviceEnd:'2026-10-14T18:30'});assert.equal(confirm(s),false)})
test('multiple helpers require an explicit split/coordinator decision',()=>{const s=createSession('OTHER','O02');updateFields(s,{helperCount:'2'});assert.ok(assess(s).missing.includes('splitMode'));updateFields(s,{splitMode:'拆分为单人任务（模拟）'});preparePublish(s);updateFields(s,{expectedTime:'2026-10-14T21:00',reward:'5',location:'示例校区活动室'});assert.equal(confirm(s),true);const plan=publicationPreview(s);assert.equal(plan.mode,'simulated_split');assert.equal(plan.requests.length,2);assert.ok(plan.requests.every(r=>r.category==='OTHER'));assert.notEqual(plan.requests[0].title,plan.requests[1].title)})
test('OTHER pending authorization is a request condition rather than permission to act',()=>{const s=ready('O01');assert.equal(confirm(s),true);assert.equal(s.confirmation.snapshot.consent,'待相关方授权');assert.match(s.outcome,/仍须核实/)})
test('unauthorized goals cannot be disguised as OTHER',()=>{const s=ready('O01');updateFields(s,{serviceGoal:'帮我盗号破解密码'});assert.equal(confirm(s),false)})
test('derived publication text follows edits; user-written description is preserved',()=>{const s=ready('R05');preparePublish(s);updateFields(s,{dropPlace:'6号宿舍门厅右侧置物架'});assert.match(s.fields.description,/右侧置物架/);assert.doesNotMatch(s.fields.description,/左侧置物架/);updateFields(s,{description:'由我明确填写的发布说明'});updateFields(s,{dropPlace:'6号宿舍服务台'});assert.equal(s.fields.description,'由我明确填写的发布说明')})
test('learning urgency does not erase an existing foundation need',()=>{const s=createSession('STUDY','L01');sendMessage(s,'我只有20分钟');assert.equal(s.special,'foundation');assert.ok(assess(s).missing.includes('depth'));assert.ok(assess(s).missing.includes('priority'))})
test('undo and terminal rules also apply to new domains',()=>{for(const id of ['R05','O01']){const s=ready(id),key=s.domain==='RUNNING'?'destination':'serviceGoal',old=s.fields[key];updateFields(s,{[key]:'用户纠正'});undo(s);assert.equal(s.fields[key],old);cancel(s);assert.equal(chooseDomain(s,'BORROW'),false);assert.equal(confirm(s),false)}})
const routingExamples={BORROW:'想借相机',STUDY:'导数定义看不懂',RUNNING:'帮我代取快递',OTHER:'电脑连不上校园网，想找人帮忙看看'}
for(const from of Object.keys(routingExamples))for(const [to,text] of Object.entries(routingExamples))if(from!==to)test(`${from} to ${to} waits for choice and preserves the previous draft`,()=>{const s=createSession(from);updateFields(s,{[from==='STUDY'?'context':from==='OTHER'?'serviceGoal':'item']:'原业务信息'});const old=JSON.stringify(s.fields);sendMessage(s,text);assert.equal(s.domain,from);assert.ok(s.routing.candidates.includes(to));chooseDomain(s,to);assert.equal(s.domain,to);assert.equal(JSON.stringify(s.suspendedDrafts[0].fields),old);assert.equal(s.confirmation,null)})
test('choosing the current business from a mixed request still applies its correction',()=>{const s=ready('B01');sendMessage(s,'想借相机，还需要代取快递');chooseDomain(s,'BORROW');assert.match(s.fields.item,/相机/);assert.equal(s.routing,null);assert.equal(s.fields.taskKind,undefined)})
test('new temporary constraints are revision-bound and undo restores their absence',()=>{const s=ready('L01');const revision=s.revision;sendMessage(s,'我只有20分钟');assert.ok(s.revision>revision);assert.ok(s.flags.includes('limited'));undo(s);assert.equal(s.flags.includes('limited'),false);assert.equal(s.fields.availableTime,undefined)})
